def construct(n, k):
    result = [0] * n
    low, high = 1, n
    for residue in range(k):
        for index in range(residue, n, k):
            if residue % 2 == 0:
                result[index] = low
                low += 1
            else:
                result[index] = high
                high -= 1
    return result

