    if bouquet_size * needed > size:
        return "-1"

    def possible(day):
        bouquets = run = 0
        for bloom_day in bloom:
            if bloom_day <= day:
                run += 1
                if run == bouquet_size:
                    bouquets += 1
                    run = 0
                    if bouquets >= needed:
                        return True
            else:
                run = 0
        return False

    low, high = min(bloom), max(bloom)
    while low < high:
        middle = (low + high) // 2
        if possible(middle):
            high = middle
        else:
            low = middle + 1
    return str(low)

