import sys

def minimum_deletions_to_sorted(s):
    tails = []
    for char in s:
        lo, hi = 0, len(tails)
        # upper_bound: equal letters may remain together in a nondecreasing subsequence.
        while lo < hi:
            mid = (lo + hi) // 2
            if tails[mid] <= char:
                lo = mid + 1
            else:
                hi = mid
        if lo == len(tails):
            tails.append(char)
        else:
            tails[lo] = char
    return len(s) - len(tails)

